-- Requirement metadata references canonical codes; no price/product master copy.
CREATE TABLE local_labor_requirement_streams (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code_key text NOT NULL UNIQUE CHECK(code_key=lower(btrim(code_key)) AND length(code_key) BETWEEN 1 AND 200),
 created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE local_labor_requirement_proposals (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),stream_id uuid NOT NULL REFERENCES local_labor_requirement_streams(id),
 owner_id text NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE local_labor_requirement_drafts (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),proposal_id uuid NOT NULL REFERENCES local_labor_requirement_proposals(id),revision integer NOT NULL CHECK(revision>0),
 semantic_fingerprint text NOT NULL CHECK(semantic_fingerprint~'^[a-f0-9]{64}$'),definition jsonb NOT NULL CHECK(jsonb_typeof(definition)='object'),
 content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'),submitted boolean NOT NULL,
 reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 3 AND 1000),created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(proposal_id,revision)
);
CREATE TABLE local_labor_requirement_events (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),stream_id uuid NOT NULL REFERENCES local_labor_requirement_streams(id),version integer NOT NULL CHECK(version>0),
 action text NOT NULL CHECK(action IN('APPROVE','RETIRE')),effective_from date NOT NULL,effective_to date CHECK(effective_to IS NULL OR effective_to>=effective_from),
 semantic_fingerprint text NOT NULL CHECK(semantic_fingerprint~'^[a-f0-9]{64}$'),definition jsonb NOT NULL CHECK(jsonb_typeof(definition)='object'),content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'),
 proposal_id uuid REFERENCES local_labor_requirement_proposals(id),proposal_revision integer,
 author_id text NOT NULL,reviewer_id text NOT NULL,reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 3 AND 1000),
 legacy_id text,legacy_version text,seed_manifest_hash text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(stream_id,version),
 CHECK((proposal_id IS NULL AND proposal_revision IS NULL AND seed_manifest_hash IS NOT NULL) OR (proposal_id IS NOT NULL AND proposal_revision>0 AND seed_manifest_hash IS NULL AND legacy_id IS NULL AND legacy_version IS NULL))
);
CREATE INDEX local_labor_requirement_effective ON local_labor_requirement_events(stream_id,effective_from,version DESC);
CREATE INDEX local_labor_requirement_owner ON local_labor_requirement_proposals(owner_id,stream_id,id);
CREATE INDEX local_labor_requirement_draft_latest ON local_labor_requirement_drafts(proposal_id,revision DESC);
CREATE TABLE local_labor_requirement_receipts (
 idempotency_key text PRIMARY KEY CHECK(length(idempotency_key) BETWEEN 1 AND 200),actor_id text NOT NULL,fingerprint text NOT NULL CHECK(fingerprint~'^[a-f0-9]{64}$'),result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE FUNCTION local_labor_requirement_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Yêu cầu mã chỉ được bổ sung phiên bản mới.'; END; $$;
CREATE TRIGGER local_labor_requirement_streams_immutable BEFORE UPDATE OR DELETE ON local_labor_requirement_streams FOR EACH ROW EXECUTE FUNCTION local_labor_requirement_immutable();
CREATE TRIGGER local_labor_requirement_proposals_immutable BEFORE UPDATE OR DELETE ON local_labor_requirement_proposals FOR EACH ROW EXECUTE FUNCTION local_labor_requirement_immutable();
CREATE TRIGGER local_labor_requirement_drafts_immutable BEFORE UPDATE OR DELETE ON local_labor_requirement_drafts FOR EACH ROW EXECUTE FUNCTION local_labor_requirement_immutable();
CREATE TRIGGER local_labor_requirement_events_immutable BEFORE UPDATE OR DELETE ON local_labor_requirement_events FOR EACH ROW EXECUTE FUNCTION local_labor_requirement_immutable();
CREATE TRIGGER local_labor_requirement_receipts_immutable BEFORE UPDATE OR DELETE ON local_labor_requirement_receipts FOR EACH ROW EXECUTE FUNCTION local_labor_requirement_immutable();
REVOKE ALL ON local_labor_requirement_streams,local_labor_requirement_proposals,local_labor_requirement_drafts,local_labor_requirement_events,local_labor_requirement_receipts FROM PUBLIC;

